class MissingValue(ValueError):
    """A placeholder has no value, or only a blank one."""


def _value_for(name, values):
    """Return the text for a placeholder or raise MissingValue."""
    value = values.get(name)
    if value is None or not str(value).strip():
        raise MissingValue(f"no value for placeholder {name!r}")
    return str(value)


def render(text, values):
    """Replace each {name} with its value; raise MissingValue if it has none."""
    return PLACEHOLDER.sub(lambda m: _value_for(m.group(1), values), text)

    def test_missing_key_raises(self):
        with self.assertRaises(MissingValue) as ctx:
            render("Hi {name}", {})
        self.assertIn("name", str(ctx.exception))

    def test_none_raises(self):
        with self.assertRaises(MissingValue):
            render("Hi {name}", {"name": None})

    def test_empty_and_blank_raise(self):
        for blank in ("", "   "):
            with self.assertRaises(MissingValue):
                render("Hi {name}", {"name": blank})

    def test_falsy_but_real_value_is_kept(self):
        self.assertEqual(render("{n} left", {"n": 0}), "0 left")

    def test_one_missing_among_many_raises(self):
        with self.assertRaises(MissingValue):
            render("{a} {b}", {"a": "x"})


